// Stand-in for next/image. Like Next, it serves resized WebP copies through
// srcset (generated by `npm run images` into public/_img) so the browser only
// downloads and decodes the size it needs.
import { forwardRef, useState } from 'react';
import manifest from './image-manifest.json';

function variants(url) {
  const widths = manifest[url];
  if (!widths) return null;
  const base = url.replace(/^\/media\//, '/_img/media/').replace(/\.[^./]+$/, '');
  return widths.map((w) => [`${base}-w${w}.webp`, w]);
}

export const Image = forwardRef(function Image(
  { src, alt = '', width, height, fill, sizes, quality, priority, preload, loading, placeholder, blurDataURL, unoptimized, overrideSrc, onLoad, style, className, ...rest },
  ref,
) {
  const [loaded, setLoaded] = useState(false);
  const url = typeof src === 'object' && src ? src.src : src;
  const sets = !unoptimized && variants(url);
  let srcSet;
  let finalSrc = url;
  if (sets) {
    if (sizes || fill) {
      srcSet = sets.map(([u, w]) => `${u} ${w}w`).join(', ');
    } else {
      // Fixed-size image: 1x and 2x density candidates, as Next does.
      const pick = (target) => (sets.find(([, w]) => w >= target) || sets[sets.length - 1])[0];
      srcSet = `${pick(width || 640)} 1x, ${pick((width || 640) * 2)} 2x`;
    }
    finalSrc = sets[sets.length - 1][0];
  }
  const blur = typeof placeholder === 'string' && placeholder.startsWith('data:') ? placeholder : placeholder === 'blur' ? blurDataURL : null;
  const s = { color: 'transparent', ...(fill ? { position: 'absolute', height: '100%', width: '100%', inset: 0 } : null), ...style };
  if (blur && !loaded) {
    Object.assign(s, {
      backgroundImage: `url("${blur}")`,
      backgroundSize: s.objectFit || 'cover',
      backgroundPosition: s.objectPosition || '50% 50%',
      backgroundRepeat: 'no-repeat',
    });
  }
  return (
    <img
      ref={ref}
      alt={alt}
      src={finalSrc}
      srcSet={srcSet}
      width={fill ? undefined : width}
      height={fill ? undefined : height}
      sizes={srcSet && (sizes || fill) ? sizes || '100vw' : undefined}
      loading={priority || preload ? 'eager' : loading ?? 'lazy'}
      fetchPriority={priority || preload ? 'high' : rest.fetchPriority}
      decoding="async"
      data-nimg={fill ? 'fill' : '1'}
      className={className}
      style={s}
      onLoad={(e) => {
        setLoaded(true);
        onLoad?.(e);
      }}
      {...rest}
    />
  );
});

export default Image;
